 "content": "def transform(grid):
    """Restore zero-masked cells by horizontal reflection of the grid."""
    h = len(grid)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        mirror_r = h - 1 - r
        for c, value in enumerate(row):
            if value == 0 and grid[mirror_r][c] != 0:
                out[r][c] = grid[mirror_r][c]
    return out
